import { useState } from 'react';
import type { ReactElement } from 'react';
import './Component.css';

export type Props = {
  initialValue: number;
  step: number;
  onChange: (value: number) => void;
};

export function Component({ initialValue, step, onChange }: Props): ReactElement {
  const [baseline] = useState<number>(initialValue);
  const [value, setValue] = useState<number>(initialValue);
  const canReset: boolean = value !== baseline;

  function changeValue(nextValue: number): void {
    setValue(nextValue);
    onChange(nextValue);
  }

  function reset(): void {
    if (!canReset) return;
    changeValue(baseline);
  }

  return (
    <div data-testid="panel" className="weighted-counter-panel">
      <output aria-label="Value">{String(value)}</output>
      <button
        type="button"
        onClick={(): void => changeValue(value + step)}
      >
        Add
      </button>
      <button
        type="button"
        onClick={(): void => changeValue(value - step)}
      >
        Subtract
      </button>
      <button type="button" disabled={!canReset} onClick={reset}>
        Reset
      </button>
    </div>
  );
}

